export function createStore(options = {}) {
  const { maxEntries = Infinity } = options;
  const data = new Map();
  const touch = (key, value) => {
    data.delete(key);
    data.set(key, value);
  };
  return {
    get(key) {
      if (!data.has(key)) return undefined;
      const value = data.get(key);
      touch(key, value);
      return value;
    },
    set(key, value) {
      touch(key, value);
      while (data.size > maxEntries) data.delete(data.keys().next().value);
    },
    keys: () => [...data.keys()],
  };
}
